'use strict';
// FAST focused REGREV 60% lab — small grid around the proven neighborhood.
const fs=require('fs'),R=JSON.parse(fs.readFileSync('data/xauusd-m5-dukascopy.json','utf8'));
const M=R.map(x=>({t:+(x.timestamp??x.time),o:+(x.open??x.o),h:+(x.high??x.h),l:+(x.low??x.l),c:+(x.close??x.c)})).filter(x=>[x.t,x.o,x.h,x.l,x.c].every(Number.isFinite)).sort((a,b)=>a.t-b.t),N=M.length,C=Math.floor(N*.75);
function ema(p){let z=[],e=M[0].c,k=2/(p+1);for(let i=0;i<N;i++){e=M[i].c*k+e*(1-k);z[i]=e}return z}function atr(){let z=Array(N).fill(NaN);for(let i=14;i<N;i++){let s=0;for(let j=i-13;j<=i;j++)s+=Math.max(M[j].h-M[j].l,Math.abs(M[j].h-M[j-1].c),Math.abs(M[j].l-M[j-1].c));z[i]=s/14}return z}const E=ema(20),A=atr();function av(i){let s=0,c=0;for(let j=i-50;j<i;j++)if(Number.isFinite(A[j])){s+=A[j];c++}return c?s/c:NaN}function S(i,q){if(A[i]/av(i)<q.ar)return;let b=M[i],r=b.h-b.l;if(!(r>0)||Math.abs(b.c-b.o)/r<q.body||[20,21,22,23].includes(new Date(b.t).getUTCHours()))return;if(q.side!=='SELL'&&(E[i]-b.c)/A[i]>=q.dist&&b.c>b.o&&(b.c-b.l)/r>=q.cp)return'BUY';if(q.side!=='BUY'&&(b.c-E[i])/A[i]>=q.dist&&b.c<b.o&&(b.h-b.c)/r>=q.cp)return'SELL'}function run(q,a,b){let T=[],o=null;for(let i=Math.max(100,a);i<Math.min(b,N-1);i++){if(o){let x=M[i],p=null;if(o.s==='BUY'){if(x.l<=o.sl)p=o.sl;else if(x.h>=o.tp)p=o.tp}else{if(x.h>=o.sl)p=o.sl;else if(x.l<=o.tp)p=o.tp}if(p==null&&i-o.e+1>=8)p=x.c;if(p!=null){T.push(o.s==='BUY'?(p-o.en)/(o.en-o.sl):(o.en-p)/(o.sl-o.en));o=null}continue}let s=S(i,q);if(!s)continue;let en=M[i+1].o,r=A[i];o={s,en,sl:s==='BUY'?en-r:en+r,tp:s==='BUY'?en+1.5*r:en-1.5*r,e:i+1}}return T}function st(t){let w=0,g=0,l=0,e=0,p=0,d=0;for(let r of t){e+=r;if(r>0){w++;g+=r}else l-=r;p=Math.max(p,e);d=Math.max(d,p-e)}return{n:t.length,wr:t.length?100*w/t.length:0,pf:l?g/l:99,nr:e,dd:d}}let Q=[];for(let side of ['BOTH','BUY','SELL'])for(let ar of [1.25,1.3,1.35])for(let dist of [2.1,2.2,2.3])for(let cp of [.65,.7,.75])for(let body of [.2,.25,.35])Q.push({side,ar,dist,cp,body});let X=Q.map(q=>({q,d:st(run(q,0,C))})).filter(x=>x.d.n>=35).sort((a,b)=>(b.d.wr-a.d.wr)||(b.d.pf-a.d.pf));console.log(`FAST REGREV 60 LAB | ${Q.length} configs only | M5=${N}`);console.log('\nTOP 25 BY DEV WR');X.slice(0,25).forEach((x,k)=>{let h=st(run(x.q,C,N));console.log(`${k+1} ${JSON.stringify(x.q)} | DEV T${x.d.n} WR${x.d.wr.toFixed(1)} PF${x.d.pf.toFixed(2)} N${x.d.nr.toFixed(2)} DD${x.d.dd.toFixed(2)} | HOLD T${h.n} WR${h.wr.toFixed(1)} PF${h.pf.toFixed(2)} N${h.nr.toFixed(2)} DD${h.dd.toFixed(2)}`)});console.log('\n60/60 SURVIVORS');let z=X.filter(x=>x.d.wr>=60&&x.d.n>=40).map(x=>({x,h:st(run(x.q,C,N))})).filter(z=>z.h.n>=15&&z.h.wr>=60&&z.h.pf>=1.3);if(!z.length)console.log('NONE');else z.slice(0,15).forEach((z,k)=>console.log(`${k+1} ${JSON.stringify(z.x.q)} | DEV ${z.x.d.n} WR${z.x.d.wr.toFixed(1)} PF${z.x.d.pf.toFixed(2)} | HOLD ${z.h.n} WR${z.h.wr.toFixed(1)} PF${z.h.pf.toFixed(2)}`));